correlation-risk.code:
vol = np.array([0.20, 0.20])                               # two assets, 20% volatility each
w = np.array([0.5, 0.5])

def port_vol(rho):
    cov = np.outer(vol, vol) * np.array([[1, rho], [rho, 1]])
    return np.sqrt(w @ cov @ w)

calm, stress = port_vol(0.2), port_vol(0.9)

kelly-criterion.code:
p, b = 0.55, 1.0                                           # win 55% of even-money bets
kelly = (p * b - (1 - p)) / b

def growth(f):                                             # expected log growth per bet
    return p * np.log(1 + b * f) + (1 - p) * np.log(1 - f)

rates = {m: growth(m * kelly) for m in (0.5, 1, 2, 2.5)}
